808	    // ── P2.5 (GrokAdamW ONLY): GLOBAL grad-norm clip coefficient. Identical to the
809	    //    decoder twin (fused_decoder_megakernel.cuh P2.5). Eager grokadamw clips the
810	    //    WHOLE grad set to grad_clip via a GLOBAL L2 norm (clip_grad_norms_device_side
811	    //    → total_norm = sqrt(Σ_i ‖g_i‖²), clip_coef = grad_clip/(total_norm+1e-6) when
812	    //    total_norm>grad_clip, else 1) BEFORE the apply. We replicate it on the REDUCED
813	    //    grad with a deterministic ascending reduction (no float atomics): each CTA sums
814	    //    a contiguous element-range into a per-CTA partial slot, CTA0 sums the partials
815	    //    in ascending CTA order → total_norm → clip_coef, broadcast via a workspace
816	    //    slot. The grad buffer is NOT mutated (the return_grad oracle + the eager-side
817	    //    clip must both see the unclipped reduced grad); the coefficient is applied
818	    //    per-element inside apply_optimizer<GrokAdamW>. Guarded so every other opt's P3
819	    //    is byte-identical (no extra barrier/work). Reuses loss_part/loss_out as free
820	    //    scratch (the reduced loss is already in *in.loss_out; the dW partials are
821	    //    consumed → that whole region after loss_out is also free).
822	    //    EXTENDED to NeuralGrok (same eager global clip; consumed in apply_optimizer<NeuralGrok>).
823	    if constexpr (Opt == OptId::GrokAdamW || Opt == OptId::NeuralGrok) {
824	        float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
825	        float* coef_bc = loss_out;           // [1] broadcast clip_coef
826	        const int64_t total_e = kVitTotalElems;
827	        const int64_t base = total_e / nCTA, rem = total_e % nCTA;
828	        const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
829	        const int64_t ecnt = base + (cta < rem ? 1 : 0);
830	        float tsum = 0.0f;
831	        for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
832	            const float gv = grad[e0 + i];
833	            tsum += gv * gv;
834	        }
835	        // Block reduction via the smem the TC GEMM already owns (sm.red, fp32).
836	        float* red = sm.red;
837	        red[threadIdx.x] = tsum;
838	        __syncthreads();
839	        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
840	            if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
841	            __syncthreads();
842	        }
843	        if (threadIdx.x == 0) sq_part[cta] = red[0];
844	        bar.sync();   // B2.5a: all per-CTA sum-of-squares partials complete
845	        if (cta == 0 && threadIdx.x == 0) {
846	            double ss = 0.0;
847	            for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
848	            const float total_norm = sqrtf((float)ss);
849	            float coef = 1.0f;
850	            if (st.grad_clip > 0.0f && total_norm > st.grad_clip)
851	                coef = st.grad_clip / (total_norm + 1e-6f);
852	            *coef_bc = coef;
853	        }
854	        bar.sync();   // B2.5b: clip_coef broadcast slot ready for all CTAs
855	        st.clip_coef = *coef_bc;   // every CTA reads the single global coefficient
856	    }
857	
858	    // ── P2.6 (Prodigy ONLY): STAGED global-d estimate (cross-ALL-tensors reduce).
859	    //    Identical to the decoder twin's P2.6. The apply tail (apply_optimizer
860	    //    <Prodigy>) reads st.d_factor (the effective LR scale d), which is a single
861	    //    cross-tensor reduction (NOT per-element) → an IN-KERNEL phase here, BYTE-
862	    //    FAITHFUL to the live eager multi-tensor path (prodigy_sm90.cuh →
863	    //    launch_multi_tensor_prodigy_fused_reduce_step, the order prodigy.py executes):
864	    //      d_prev  = persisted d_lr  (step 1: d0 cold-start — the zero-init state slot
865	    //                is 0 but eager inits _d_lr=d0=1e-6, so seed it here)
866	    //      r_ema  <- beta3·r_ema + Σ d_prev²·<g, p0−p>     (decay persisted SCALAR,
867	    //      s_ema  <- beta3·s_ema + Σ d_prev²·|g|            then add this step's Σ)
868	    //      d       = max(d_prev, d_coef·r_ema/|s_ema|)      (prodigy_update_d; d_coef
869	    //                scales ONLY the candidate — persisted r_ema stays UNSCALED)
870	    //    phaseA publishes per-CTA (r,s) into opt_reduce slots (owner-computes tree,
871	    //    no float atomic, deterministic); a grid barrier; CTA0 owner-sums ascending,
872	    //    EMA-decays, updates d, broadcasts. Guarded so every other opt is byte-
873	    //    identical (no extra barrier/work). p0 (param_init) is the trajectory anchor.
874	    // DETERMINISM — FIXED-PARTITION reduction (mirrors the A/A/A-CLEAN GrokAdamW
875	    // P2.5 above + the decoder twin's P2.6), NOT the work-steal task-queue drain.
876	    // WHY THIS SHAPE (the A/A/A determinism leg): the work-steal phaseA drained the
877	    // global TaskQueue (atomicAdd(g_next_task)) in timing-dependent claim order, so
878	    // each CTA's (r,s) slot could be a different tensor subset run-to-run; with non-
879	    // associative fp32 add the partials then regroup differently and the owner's d can
880	    // differ at ULP level from step>=2 — a COMPONENT_CONTRACT deterministic-reduction
881	    // violation (not guaranteed reproducible BY CONSTRUCTION, even where empirically
882	    // bit-exact on a given GPU). A FIXED contiguous element range per CTA over the
883	    // FLAT [0,kVitTotalElems) arrays (params/param_init/grad are parallel flat blobs
884	    // → flat Σ == cross-tensor Σ) with a plain sync() is the IDENTICAL shape as the
885	    // A/A/A-CLEAN GrokAdamW P2.5 — deterministic by construction. Per-element math
886	    // still CALLS canonical prodigy_partials_step (prodigy.h, single-source).
887	    // g_next_task is UNTOUCHED (B2 reset it), so P3's drain is unchanged — no
888	    // sync_reset in P2.6.
889	    if constexpr (Opt == OptId::Prodigy) {
890	        float* r_part = opt_reduce;                  // [nCTA] per-CTA Σ d²·<g,p0−p>
891	        float* s_part = opt_reduce + nCTA;           // [nCTA] per-CTA Σ d²·|g|
892	        float* d_bc   = opt_reduce + 2 * nCTA;       // [1] reduced-d broadcast
893	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
894	        const int64_t total_p = kVitTotalElems;
895	        const int64_t pbase = total_p / nCTA, prem = total_p % nCTA;
896	        const int64_t pe0 = (int64_t)cta * pbase + (cta < prem ? cta : prem);
897	        const int64_t pecnt = pbase + (cta < prem ? 1 : 0);
898	        float r_acc = 0.0f, s_acc = 0.0f;
899	        for (int64_t i = threadIdx.x; i < pecnt; i += blockDim.x) {
900	            algo::prodigy_partials_step(params, st.param_init, grad,
901	                                        d_prev, pe0 + i, r_acc, s_acc);
902	        }
903	        float r_block, s_block;
904	        prim::block_reduce_sum2_f32(r_acc, s_acc, r_block, s_block);
905	        if (threadIdx.x == 0) { r_part[cta] = r_block; s_part[cta] = s_block; }
906	        bar.sync();   // B2.6a: all per-CTA (r,s) partials published & visible
907	        if (cta == 0 && threadIdx.x == 0) {
908	            float r_step = 0.0f, s_step = 0.0f;     // ascending-CTA owner-sum
909	            for (int c = 0; c < nCTA; ++c) { r_step += r_part[c]; s_step += s_part[c]; }
910	            const float r_ema = st.beta3 * st.prodigy_persist[0] + r_step;
911	            const float s_ema = st.beta3 * st.prodigy_persist[1] + s_step;
912	            const float d_new = algo::prodigy_update_d(d_prev, st.d_coef * r_ema, s_ema);
913	            st.prodigy_persist[0] = r_ema;          // persist UNSCALED EMA
914	            st.prodigy_persist[1] = s_ema;
915	            st.prodigy_persist[2] = d_new;          // persisted d_lr for next step
916	            d_bc[0]               = d_new;          // broadcast to all CTAs
917	        }
918	        bar.sync();   // B2.6b: d visible to every CTA before the apply
919	        st.d_factor = d_bc[0];                      // the reduced d the tail reads
920	    }
