922	    // ── P2.7 (Muon ONLY): grid-cooperative Newton-Schulz orthogonalization of the
923	    //    2D weights (INTEGRATION-OPTSTAGES §3). For EACH 2D matrix (kVitMuon2D) all
924	    //    CTAs cooperate: buf=μ·buf+g (buf is the PERSISTENT m-slice — momentum state,
925	    //    NOT transient), ‖buf‖_F via per-CTA partials → inv_norm, X=buf·inv_norm,
926	    //    then ns_steps × { A=XXᵀ → AX=A·X → AAX=A·AX → orth=a·X+b·AX+c·AAX, swap },
927	    //    then the canonical muon_update_step apply (decay·p + neg_lr_scale·orth). The
928	    //    1D / non-2D weights (cls_token, biases, LN γ/β) take the AdamW tail in P3.
929	    //    The elementwise bodies CALL muon.h (muon_momentum_normalize_step via the
930	    //    phaseA buf body, muon_ns_combine_step, muon_update_step); the matmuls are the
931	    //    cited new device code (the eager path delegates to torch::mm/cuBLAS). Guarded
932	    //    so every other opt is byte-identical (no extra barriers / work).
933	    if constexpr (Opt == OptId::Muon) {
934	        // Carve the per-matrix NS scratch (sized for the largest 2D weight).
935	        PrecomputeWorkspace pw{};
936	        pw.muon_X            = muon_base;
937	        pw.muon_AX           = pw.muon_X   + kVitMuonMaxNumel;
938	        pw.muon_AAX          = pw.muon_AX  + kVitMuonMaxNumel;
939	        pw.muon_orth         = pw.muon_AAX + kVitMuonMaxNumel;
940	        pw.muon_A            = pw.muon_orth + kVitMuonMaxNumel;
941	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)kVitMuonMaxRows * kVitMuonMaxRows;
942	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
943	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
944	        const int   ns_steps = 5;                 // bindings.cpp default
945	        for (int mi = 0; mi < vittc::kVitNumMuon2D; ++mi) {
946	            const vittc::VitMuon2D M = vittc::kVitMuon2D[mi];
947	            const int rows = M.rows, cols = M.cols;
948	            const int64_t numel = (int64_t)rows * cols;
949	            const int64_t off   = (int64_t)kVitOffsets[M.tidx];
950	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
951	            pw.muon_buf = st.exp_avg + off;
952	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
953	            muon_momentum_norm_phaseA(grad + off, numel, momentum, pw);
954	            bar.sync();
955	            muon_norm_reduce_phaseB(ctx, pw);
956	            bar.sync();
957	            muon_scale_X(numel, pw);
958	            bar.sync();
959	            // NS iterations. After each combine, orth holds the new iterate; swap so
960	            // the next iteration reads it as X. ns_steps swaps → final result is in
961	            // muon_X iff ns_steps even else muon_orth (we track the parity below).
962	            for (int s = 0; s < ns_steps; ++s) {
963	                // A = X Xᵀ  (M=rows,N=rows,K=cols; B transposed).
964	                muon_matmul(pw.muon_X, pw.muon_X, pw.muon_A, rows, rows, cols, cols, cols, /*bT=*/true);
965	                bar.sync();
966	                // AX = A X   (M=rows,N=cols,K=rows).
967	                muon_matmul(pw.muon_A, pw.muon_X, pw.muon_AX, rows, cols, rows, rows, cols, /*bT=*/false);
968	                bar.sync();
969	                // AAX = A (AX) (M=rows,N=cols,K=rows).
970	                muon_matmul(pw.muon_A, pw.muon_AX, pw.muon_AAX, rows, cols, rows, rows, cols, /*bT=*/false);
971	                bar.sync();
972	                muon_ns_combine_phase(numel, pw);   // orth = a·X + b·AX + c·AAX
973	                bar.sync();
974	                // swap X <-> orth (next iter reads X; final result tracked by parity).
975	                float* tmp = pw.muon_X; pw.muon_X = pw.muon_orth; pw.muon_orth = tmp;
976	            }
977	            // After ns_steps swaps the final orthogonalized matrix is in muon_X (the
978	            // last combine wrote muon_orth, then we swapped → muon_X). Apply Muon:
979	            //   p = decay_factor·p + neg_lr_scale·orth   (muon.h:63-73)
980	            const float scale        = 0.2f * sqrtf((float)(rows > cols ? rows : cols));
981	            const float neg_lr_scale = -lr * scale;
982	            const float decay_factor = 1.0f - lr * st.wd;
983	            float* __restrict__ p = params + off;
984	            const float* __restrict__ orth_final = pw.muon_X;   // post-swap result
985	            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
986	            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < numel; i += gstride)
987	                p[i] = decay_factor * p[i] + neg_lr_scale * orth_final[i];
988	            bar.sync();   // matrix done; all CTAs synchronized before the next matrix
989	        }
990	    }
991	
992	    // ── P2.45 (SuperGrok11/15 ONLY) staged into P3: the per-TENSOR meta-net mu
993	    //    precompute (INTEGRATION-OPTSTAGES §4/§5) — ViT twin of the decoder's. SINGLE
994	    //    task-queue drain, NO grid barrier (each tensor is self-contained: mu(T) +
995	    //    SG11's per-tensor cosine gate(T) depend ONLY on T's elements). The phi weights
996	    //    (per-TENSOR weight set) stage to SMEM ONCE per block before the drain; SG15's
997	    //    gate is the host scalar st.gate. sharpness was produced by P2.4 (or cached).
998	    __shared__ float sg_sW1[kSgPhiHidden * 2];
999	    __shared__ float sg_sb1[kSgPhiHidden];
1000	    __shared__ float sg_sW2[kSgPhiHidden];
1001	    if constexpr (Opt == OptId::SuperGrok11 || Opt == OptId::SuperGrok15) {
1002	        sg_stage_phi_weights<kSgPhiHidden>(st.sg_phi_W1, st.sg_phi_b1, st.sg_phi_W2,
1003	                                           sg_sW1, sg_sb1, sg_sW2);   // syncs
1004	    }
1005	
1006	    // ── P3-SG2 (SuperGrok2 ONLY) — the ViT twin of the decoder's P3-SG2 phase. The
1007	    //    FULL CSA/HCA/PEER/GRU meta-net as the optimizer phase, run INSTEAD of the
1008	    //    per-element apply_optimizer<SuperGrok2> stub. Each CTA work-steals WHOLE
1009	    //    tensors and runs sg2_meta_stages (STAGE -1 in-kernel segmented sort → S0..S5)
1010	    //    reading st.sharpness (P2.4 SAM 2nd backward) + the HBM meta-net bundle. The
1011	    //    kernel returns after this. if-constexpr'd to SuperGrok2 ⇒ every other cell is
1012	    //    byte-identical.
1013	    if constexpr (Opt == OptId::SuperGrok2) {
1014	        SG2Weights w2{
1015	            st.sg2_input_proj_W, st.sg2_input_proj_b,
1016	            st.sg2_csa_q_W, st.sg2_csa_k_W, st.sg2_csa_v_W, st.sg2_csa_out_W,
1017	            st.sg2_csa_compress_w, st.sg2_csa_idx_DQ, st.sg2_csa_idx_K,
1018	            st.sg2_hca_q_W, st.sg2_hca_k_W, st.sg2_hca_v_W, st.sg2_hca_out_W,
1019	            st.sg2_gru_Wz, st.sg2_gru_bz, st.sg2_gru_Wr, st.sg2_gru_br,
1020	            st.sg2_gru_Wh, st.sg2_gru_bh,
1021	            st.sg2_peer_query_Ws, st.sg2_prod_keys_A, st.sg2_prod_keys_B,
1022	            st.sg2_expert_W1, st.sg2_expert_b1, st.sg2_expert_W2, st.sg2_expert_b2};
1023	        SG2Scalars sc2{
1024	            st.sg2_alpha, st.sg2_gru_decay, st.sg2_lamb_eff,
1025	            st.sg2_beta1, st.sg2_bc1, st.sg2_bc2,
1026	            st.sg2_rescale, st.beta2, lr, st.wd, st.eps};
1027	        float* sg2_base = sg2_ws_base + (int64_t)blockIdx.x * vit_sg2_ws_stride_floats();
1028	        int64_t* row_off64 = reinterpret_cast<int64_t*>(sg2_base);
1029	        for (int t = threadIdx.x; t < kVitNumTensors; t += blockDim.x)
1030	            row_off64[t] = (int64_t)kVitOffsets[t];
1031	        float* sg2_meta_ws = sg2_base + 2 * kVitNumTensors;
1032	        __syncthreads();
1033	        SG2State stt{};
1034	        stt.exp_avg     = st.exp_avg;
1035	        stt.exp_avg_sq  = st.exp_avg_sq;
1036	        stt.mu          = const_cast<float*>(st.mu);
1037	        stt.slow        = st.sg2_slow;
1038	        stt.gru_state   = st.sg2_gru_state;
1039	        stt.perm        = nullptr;
1040	        stt.unsort      = nullptr;
1041	        stt.workspace   = sg2_meta_ws;
1042	        stt.ws_stride   = sg2_ws_stride<VitSG2Dims>((int64_t)kVitSG2Nmax);
1043	        stt.n_tensors   = kVitNumTensors;
1044	        stt.n           = kVitSizes;
1045	        stt.row_off     = row_off64;
1046	        __shared__ int task_slot2;
1047	        TaskQueue q2 = ctx.queue();
1048	        for (int t = q2.next_block(&task_slot2); t < kVitNumTensors;
1049	             t = q2.next_block(&task_slot2)) {
1050	            sg2_meta_stages<VitSG2Dims, SG2Weights, float, float, /*BuildSort=*/true>(
1051	                w2, t, stt, sc2, params, grad, st.sharpness, sg2_meta_ws);
1052	        }
1053	        return;   // SG2 owns the whole optimizer phase; skip P3.
1054	    }
1055	
1056	    // ── P3: scalar optimizer tail over the reduced grad (REUSED verbatim). ──
1057	    st.lr = lr;
1058	#ifdef SG_VIT_PROFILE
1059	    unsigned long long _p3a = (threadIdx.x == 0) ? clock64() : 0;
1060	#endif
1061	    {
1062	        __shared__ int task_slot;
1063	        TaskQueue q = ctx.queue();
1064	        for (int t = q.next_block(&task_slot); t < kVitNumTensors;
1065	             t = q.next_block(&task_slot)) {
1066	            const int n = kVitSizes[t];
1067	            const int64_t off = (int64_t)kVitOffsets[t];
1068	            // MUON: the 2D matrices were orthogonalized + applied in P2.7; P3 handles
1069	            //   ONLY the 1D / non-2D weights, which take the AdamW tail (muon.h:75-76,
1070	            //   the eager Muon auto-split). Skip the 2D ones here (already done).
1071	            if constexpr (Opt == OptId::Muon) {
1072	                if (vittc::vit_is_muon_2d(t)) continue;
1073	            }
1074	            FusedOptState ts = vit_rebase_state<Opt>(st, off);
1075	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only): β1_i = β1·(1-γ)^t,
1076	            //     t == the tensor's flat named_parameters() layer index (the
1077	            //     work-steal task id maps 1:1 to kVitOffsets order == the eager
1078	            //     enumeration order — cls_token is t=0). bc1 must be rebased TOO
1079	            //     (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager; bc2 stays global.
1080	            if constexpr (Opt == OptId::GrokAdamW) {
1081	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
1082	                ts.beta1 = b1;
1083	                ts.bc1   = 1.0f - powf(b1, (float)step);
1084	            }
1085	            // SuperGrok11/15 meta-net mu (+ SG11 per-tensor gate) precompute for THIS
1086	            // tensor, BEFORE the apply reads ts.mu/ts.gate (ViT twin of the decoder's).
1087	            if constexpr (Opt == OptId::SuperGrok11) {
1088	                const float b2 = (st.sg_phi_W2 != nullptr) ? st.sg_phi_W2[kSgPhiHidden]
1089	                                                           : st.sg_phi_b2;
1090	                // st.exp_avg = start-of-step momentum (base ptr, indexed by off+i) —
1091	                // the gate's 2nd cosine operand: sigmoid(gate_temp·cos(grad,momentum)).
1092	                // Precompute runs BEFORE the apply (sg11_sweep_b_step) writes exp_avg.
1093	                const float g8 = sg11_precompute_mu_and_gate_for_tensor<kSgPhiHidden>(
1094	                    st.mu, grad, st.sharpness, st.exp_avg, sg_sW1, sg_sb1, sg_sW2,
1095	                    b2, st.sg_rescale, off, n, st.gate_temp);
1096	                ts.gate = g8;            // per-tensor gate=sigmoid(gate_temp·cos) the apply tail reads
1097	                __syncthreads();         // mu(T) fully written + gate broadcast before apply
1098	            } else if constexpr (Opt == OptId::SuperGrok15) {
1099	                const float b2 = (st.sg_phi_W2 != nullptr) ? st.sg_phi_W2[kSgPhiHidden]
1100	                                                           : st.sg_phi_b2;
1101	                sg15_precompute_mu_for_tensor<kSgPhiHidden>(
1102	                    st.mu, grad, st.sharpness, sg_sW1, sg_sb1, sg_sW2,
1103	                    b2, st.sg_rescale, off, n);
1104	                // ts.gate stays = st.gate (the host sigmoid(accuracy) scalar).
1105	                __syncthreads();         // mu(T) visible before the apply reads it
1106	            }
1107	            float* __restrict__ p = params + off;
1108	            const float* __restrict__ gg = grad + off;
1109	            if constexpr (Opt == OptId::Muon) {
1110	                // 1D / non-2D weights: the canonical AdamW tail (muon.py:115-125 routes
1111	                // non-matrix params to a SEPARATE AdamW group with INDEPENDENT
1112	                // hyperparameters — adamw_lr/adamw_betas — NOT the 2D Muon lr/momentum).
1113	                // ts.lr/ts.beta1 carry the 2D-group's (lr=0.02, momentum=0.95), so the
1114	                // 1D tail MUST instead use the aux_* fields (eager adamw_lr/adamw_betas).
1115	                // weight_decay is SHARED across both eager groups (muon.py:122) → ts.wd
1116	                // stays. eps is the eager adamw_eps (= ts.eps, mapped by _opt_scalars_from).
1117	                // bc1/bc2 are device-computed here from aux_beta^step (kept out of the
1118	                // mirror to shrink the host ABI surface; fp32 powf, tol 2e-3 is ample).
1119	                // apply_optimizer<Muon> would deref st.orth (NS dir, only valid for 2D),
1120	                // so route directly to adamw_step with the aux hyperparameters.
1121	                const float a_bc1 = 1.0f - powf(st.aux_beta1, (float)step);
1122	                const float a_bc2 = 1.0f - powf(st.aux_beta2, (float)step);
1123	                for (int i = threadIdx.x; i < n; i += blockDim.x)
1124	                    algo::adamw_step<float, float>(
1125	                        p, ts.exp_avg, ts.exp_avg_sq, gg,
1126	                        st.aux_lr, st.aux_beta1, st.aux_beta2, ts.eps, ts.wd,
1127	                        a_bc1, a_bc2, (int64_t)i);
1128	            } else {
1129	                for (int i = threadIdx.x; i < n; i += blockDim.x)
1130	                    apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
1131	            }
1132	        }
1133	    }
1134	#ifdef SG_VIT_PROFILE
1135	    if (threadIdx.x == 0) { unsigned long long _p3b = clock64(); atomicMax(&g_vit_prof_max[5], _p3b - _p3a); }
1136	#endif
1137	}
