602	// (dX) dX[M,Kin] = dY[M,Nout] @ W[Nout,Kin].  N(wgmma)=Kin (tiled by width N),
603	// K=Nout. W staged transposed: srcB(n=kin,k=out)=W[out·Kin+kin] (fp32→bf16).
604	// Writes fp32 dX [M,Kin].
605	template <int N>
606	__device__ __forceinline__ void vittc_gemm_dx_f32(
607	        const __nv_bfloat16* __restrict__ dY, const float* __restrict__ W,
608	        float* __restrict__ dXf32, int Kin, int Nout
609	        SG_VIT_P1_MATOMS_PARAM_F32 SG_VIT_P1_MREAL_PARAM,
610	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
611	    const int k_steps = Nout / wgs::kWgmmaAtomK;
612	    for (int n0 = 0; n0 < Kin; n0 += N) {
613	        const int n_real = (Kin - n0) < N ? (Kin - n0) : N;
614	        auto srcA = [&] (int m, int k) -> __nv_bfloat16 { return dY[(int64_t)m * Nout + k]; };
615	        auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
616	            int nn = n0 + n; return nn < Kin ? __float2bfloat16(W[(int64_t)k * Kin + nn]) : __float2bfloat16(0.f); };
617	        auto out  = [&] (int m, int n, float v) { dXf32[(int64_t)m * Kin + n0 + n] = v; };
618	        tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kAtomsM>(
619	            0, SG_VIT_P1_MATOMS_ARG_F32, n_real, k_steps SG_VIT_P1_MREAL_ARG, srcA, srcB, out, sA, sB);
620	    }
621	}
