623	// ════════════════════════════════════════════════════════════════════════
624	//  Per-CTA TILE SCRATCH (HBM). One tile's forward intermediates the backward
625	//  reads, reused across the tiles a CTA grid-strides over. Sized for kTileM
626	//  rows. DEDICATED, NON-ALIASED buffers per fp32 intermediate (HBM is not
627	//  scarce; the aliasing bug class is avoided). qkv/ff0pre/attn/n1·n2 caches are
628	//  [kLayers]-indexed (the fwd runs ALL layers then bwd runs ALL layers, so each
629	//  layer's bwd-read state must persist per layer — the "layer-0 grads wrong"
630	//  bug). fnx/fni (final norm) + transient dh/x1/finalin/logits/work/work2/dsc
631	//  stay single.
632	// ════════════════════════════════════════════════════════════════════════
633	constexpr int kNSampPerTile  = kTileM / vit::kSeq;
634	constexpr int kAttnPerTile   = kNSampPerTile * vit::kHeads * vit::kSeq * vit::kSeq;
635	constexpr int kLogitsPerTile = kNSampPerTile * vit::kVocab;
636	
637	struct VitTileScratch {
638	    __nv_bfloat16* qkv[vit::kLayers];     // [kTileM, 3d]  per layer
639	    __nv_bfloat16* ff0pre[vit::kLayers];  // [kTileM, dff] per layer
640	    float* attn[vit::kLayers];            // [kAttnPerTile] per layer
641	    float* n1x[vit::kLayers]; float* n1i[vit::kLayers];
642	    float* n2x[vit::kLayers]; float* n2i[vit::kLayers];
643	    float* dsc;             // [kAttnPerTile] attention dscores (transient, bwd-only)
644	    float* fnx; float* fni; // final-norm LN caches (single)
645	    float* dh;              // [kTileM, d]    running adjoint wrt block output
646	    float* x1;              // [kTileM, d]    n1 output (fp32, residual base for r2)
647	    float* finalin;         // [kTileM, d]    last-layer n2 output (fp32, head input)
648	    float* logits;          // [kLogitsPerTile] per-sample CLS-pos logits (fp32)
649	    float* work;            // [kTileM, dff]  GEMM output / general fp32 scratch
650	    float* work2;           // [kTileM, dff]  second fp32 scratch (bwd dx1/dqkv)
651	};
652	
653	__host__ __device__ __forceinline__ int64_t vit_tile_scratch_bf16_count() {
654	    return (int64_t)vit::kLayers * ((int64_t)kTileM * 3 * vit::kD + (int64_t)kTileM * vit::kDff);
655	}
656	__host__ __device__ __forceinline__ int64_t vit_tile_scratch_f32_count() {
657	    return (int64_t)vit::kLayers * (
658	             (int64_t)kAttnPerTile
659	           + 2 * ((int64_t)kTileM * vit::kD + kTileM))
660	         + (int64_t)kAttnPerTile                          // dsc (single)
661	         + ((int64_t)kTileM * vit::kD + kTileM)           // fn xhat+inv (single)
662	         + (int64_t)kTileM * vit::kD                      // dh
663	         + (int64_t)kTileM * vit::kD                      // x1
664	         + (int64_t)kTileM * vit::kD                      // finalin
665	         + (int64_t)kLogitsPerTile                        // logits
666	         + 2 * (int64_t)kTileM * vit::kDff;               // work + work2
667	}
668	__host__ __device__ __forceinline__ int64_t vit_tile_scratch_total_f32() {
669	    return (vit_tile_scratch_bf16_count() + 1) / 2 + vit_tile_scratch_f32_count();
670	}
671	
672	__device__ __forceinline__ VitTileScratch vit_tile_scratch_bind(float* slab) {
673	    VitTileScratch s;
674	    __nv_bfloat16* b = reinterpret_cast<__nv_bfloat16*>(slab);
675	    int64_t bo = 0;
676	    for (int li = 0; li < vit::kLayers; ++li) { s.qkv[li]    = b + bo; bo += (int64_t)kTileM * 3 * vit::kD; }
677	    for (int li = 0; li < vit::kLayers; ++li) { s.ff0pre[li] = b + bo; bo += (int64_t)kTileM * vit::kDff; }
678	    float* f = slab + (vit_tile_scratch_bf16_count() + 1) / 2;
679	    int64_t fo = 0;
680	    for (int li = 0; li < vit::kLayers; ++li) { s.attn[li] = f + fo; fo += kAttnPerTile; }
681	    for (int li = 0; li < vit::kLayers; ++li) { s.n1x[li] = f + fo; fo += (int64_t)kTileM * vit::kD; s.n1i[li] = f + fo; fo += kTileM; }
682	    for (int li = 0; li < vit::kLayers; ++li) { s.n2x[li] = f + fo; fo += (int64_t)kTileM * vit::kD; s.n2i[li] = f + fo; fo += kTileM; }
683	    s.dsc  = f + fo; fo += kAttnPerTile;
684	    s.fnx  = f + fo; fo += (int64_t)kTileM * vit::kD;
685	    s.fni  = f + fo; fo += kTileM;
686	    s.dh   = f + fo; fo += (int64_t)kTileM * vit::kD;
687	    s.x1   = f + fo; fo += (int64_t)kTileM * vit::kD;
688	    s.finalin = f + fo; fo += (int64_t)kTileM * vit::kD;
689	    s.logits  = f + fo; fo += kLogitsPerTile;
690	    s.work    = f + fo; fo += (int64_t)kTileM * vit::kDff;
691	    s.work2   = f + fo; fo += (int64_t)kTileM * vit::kDff;
692	    return s;
693	}
