695	// ════════════════════════════════════════════════════════════════════════
696	//  TILE-AWARE SCALAR ELEMENTWISE STAGES (fp32, CTA-cooperative over kTileM
697	//  rows). Mirror the scalar oracle's per-row math (model_stage_vit.cuh) but
698	//  operate on a whole tile of `nrows` rows at once over HBM [rows×width].
699	//  Reductions reuse vit_block_sum / vit_block_max (whole-block, looped per row).
700	//  `red` is a 256-float smem reduction slot.
701	// ════════════════════════════════════════════════════════════════════════
702	
703	// LayerNorm fwd over the last dim d, for `nrows` rows. y/xhat fp32 HBM [rows×d];
704	// inv fp32 HBM [rows]. gamma/beta fp32 [d]. Caches xhat+inv for the bwd.
705	__device__ __forceinline__ void vittc_ln_fwd_tile(
706	        const float* __restrict__ x, const float* __restrict__ gamma,
707	        const float* __restrict__ beta, int nrows,
708	        float* __restrict__ y, float* __restrict__ xhat, float* __restrict__ inv,
709	        float* red) {
710	    for (int s = 0; s < nrows; ++s) {
711	        const float* xr = x + (int64_t)s * vit::kD;
712	        float sum = 0.0f;
713	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) sum += xr[j];
714	        float mean = vit_block_sum(sum, red) / (float)vit::kD;
715	        float vs = 0.0f;
716	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) { float c = xr[j] - mean; vs += c * c; }
717	        float var = vit_block_sum(vs, red) / (float)vit::kD;
718	        float iv = rsqrtf(var + vit::kLnEps);
719	        if (threadIdx.x == 0) inv[s] = iv;
720	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
721	            float xh = (xr[j] - mean) * iv;
722	            xhat[(int64_t)s * vit::kD + j] = xh;
723	            y[(int64_t)s * vit::kD + j] = xh * gamma[j] + beta[j];
724	        }
725	        __syncthreads();
726	    }
727	}
728	
729	// LayerNorm bwd for `nrows` rows: dy [rows×d] fp32, cached xhat/inv → dx [rows×d]
730	// fp32; ACCUMULATES dgamma/dbeta (summed over the tile's rows) into a per-CTA
731	// LN-vec partial slot gw/gb [d] (plain += : single owner thread per feature j
732	// across rows, deterministic — same rule as the scalar vit_layernorm_bwd).
733	__device__ __forceinline__ void vittc_ln_bwd_tile(
734	        const float* __restrict__ dy, const float* __restrict__ xhat,
735	        const float* __restrict__ inv, const float* __restrict__ gamma, int nrows,
736	        float* __restrict__ dx, float* __restrict__ gw, float* __restrict__ gb,
737	        float* red) {
738	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
739	        float dgw = 0.0f, dgb = 0.0f;
740	        for (int s = 0; s < nrows; ++s) {
741	            float d = dy[(int64_t)s * vit::kD + j];
742	            dgb += d; dgw += d * xhat[(int64_t)s * vit::kD + j];
743	        }
744	        gw[j] += dgw; gb[j] += dgb;
745	    }
746	    for (int s = 0; s < nrows; ++s) {
747	        const float* dyr = dy + (int64_t)s * vit::kD;
748	        const float* xhr = xhat + (int64_t)s * vit::kD;
749	        float sda = 0.0f, sdax = 0.0f;
750	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
751	            float dxhat = dyr[j] * gamma[j]; sda += dxhat; sdax += dxhat * xhr[j];
752	        }
753	        sda = vit_block_sum(sda, red);
754	        sdax = vit_block_sum(sdax, red);
755	        float iv = inv[s];
756	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
757	            float dxhat = dyr[j] * gamma[j];
758	            dx[(int64_t)s * vit::kD + j] = iv * (dxhat - (sda + xhr[j] * sdax) / (float)vit::kD);
759	        }
760	        __syncthreads();
761	    }
762	}
