1259	//  P2 — OUTPUT-STATIONARY dW. Each of the 10 weight matrices (patch_proj +
1260	//  in/out/ff0/ff2 ×L + head) dW = dYᵀ @ X is split into 64×N output tiles;
1261	//  tile_id % nCTA owns each. The owner CTA contracts the FULL token dim itself
1262	//  (ascending-t, no float atomics, no partials) via the validated dW
1263	//  orientation. Writes the tile into `grad`.
1264	//
1265	//  patch_proj dW = dh0_patch^T @ X_patch (K = Tp = nsamp·16; the patch rows of
1266	//  dh0, gathered against the patch token rows). The 9 transformer dW use K=T (B
1267	//  for the head). To unify, each spec carries an `X_is_patch` flag: when set,
1268	//  the dW contracts over the Tp PATCH rows, reading the dY adjoint from dh0's
1269	//  patch rows (via a global→patch-row map) and X from X_patch.
1270	// ════════════════════════════════════════════════════════════════════════
1271	struct VitDwSpec {
1272	    const __nv_bfloat16* dY;   // [K, Nout]  (for patch_proj: nullptr — uses dh0)
1273	    const __nv_bfloat16* X;    // [K, Kin]
1274	    int Nout; int Kin; int K;  // Kin = REAL in-dim; K = contraction length
1275	    int Kpad;                  // Kin padded to a multiple of 16 (=64 for patch_proj's Kin=49)... see note
1276	    int grad_off;              // element offset of this weight in `grad`
1277	    int bias_off;              // element offset of the bias in `grad`
1278	    int kind;                  // 0=transformer (dY/X both token rows), 1=patch_proj
1279	};
1280	
1281	// Build the 10 specs (called by all CTAs; cheap). T = B*kSeq; Tp = B*kNPatch.
1282	__device__ __forceinline__ void vittc_build_dw_specs(
1283	        const VitActs& acts, int B, int T, int Tp, VitDwSpec spec[10]) {
1284	    // vit_layout weight tensor indices (and bias idx). Per-layer block base = 4 + li*12:
1285	    //   in_w = base+0 (in_b base+1), out_w base+2 (out_b base+3),
1286	    //   ff0_w base+8 (ff0_b base+9), ff2_w base+10 (ff2_b base+11).
1287	    //   patch_proj.weight=1 (bias=2); head out.weight=30 (out.bias=31).
1288	    // spec[0] = patch_proj; spec[1..8] = transformer (li,kind); spec[9] = head.
1289	    {
1290	        VitDwSpec& sp = spec[0];
1291	        sp.dY = nullptr; sp.X = acts.X_patch; sp.Nout = vit::kD; sp.Kin = vit::kPatch;
1292	        sp.K = Tp; sp.Kpad = vit::kPatch;  // K (contraction over patch rows) IS Tp; Kin padding handled in run_tile
1293	        sp.grad_off = kVitOffsets[1]; sp.bias_off = kVitOffsets[2]; sp.kind = 1;
1294	    }
1295	    for (int s = 0; s < 8; ++s) {
1296	        const int li = s / 4, kk = s % 4;
1297	        const int base = 4 + li * 12;
1298	        VitDwSpec& sp = spec[1 + s];
1299	        sp.K = T; sp.kind = 0; sp.Kpad = 0;
1300	        if (kk == 0)      { sp.dY = acts.dY_qkv[li]; sp.X = acts.X_in[li];  sp.Nout = 3 * vit::kD; sp.Kin = vit::kD;   sp.grad_off = kVitOffsets[base + 0]; sp.bias_off = kVitOffsets[base + 1]; }
1301	        else if (kk == 1) { sp.dY = acts.dY_a[li];   sp.X = acts.X_ctx[li]; sp.Nout = vit::kD;     sp.Kin = vit::kD;   sp.grad_off = kVitOffsets[base + 2]; sp.bias_off = kVitOffsets[base + 3]; }
1302	        else if (kk == 2) { sp.dY = acts.dY_ff0[li]; sp.X = acts.X_x1[li];  sp.Nout = vit::kDff;   sp.Kin = vit::kD;   sp.grad_off = kVitOffsets[base + 8]; sp.bias_off = kVitOffsets[base + 9]; }
1303	        else              { sp.dY = acts.dY_ff2[li]; sp.X = acts.X_gact[li];sp.Nout = vit::kD;     sp.Kin = vit::kDff; sp.grad_off = kVitOffsets[base + 10]; sp.bias_off = kVitOffsets[base + 11]; }
1304	    }
1305	    VitDwSpec& hd = spec[9];
1306	    hd.dY = acts.dY_logits; hd.X = acts.X_hn; hd.Nout = vit::kVocab; hd.Kin = vit::kD; hd.K = B; hd.kind = 0; hd.Kpad = 0;
1307	    hd.grad_off = kVitOffsets[30]; hd.bias_off = kVitOffsets[31];
1308	}
