1403	// ════════════════════════════════════════════════════════════════════════
1404	//  SPLIT-K dW (multi-CTA tiling — the validated decoder/mamba win, ported to
1405	//  ViT). The 10 dW yield only ~52 output tiles → ~60% of 132 SMs idle in P2.
1406	//  Split-K turns each output tile into G work items (one per K-chunk): each CTA
1407	//  computes a PARTIAL over its K-chunk into a per-(tile,chunk) scratch slot; a
1408	//  grid barrier; then a DETERMINISTIC ascending-chunk reduce sums the G partials
1409	//  into grad — no float atomics, fixed order, so parity + A/A/A bit-determinism
1410	//  hold (each partial is the SAME ascending-k fp32 wgmma accumulate; Σ_chunk ==
1411	//  full-K sum reassociated into G fp32 blocks). G==1 routes to the single-CTA
1412	//  vittc_dw_run_tile above (no scratch). Slot (gt,kc) at
1413	//  dw_part[(gt*G+kc) * (64*kVitMaxTileN) + row*kVitMaxTileN + col].
1414	//
1415	//  ViT delta vs the decoder split-K: the patch_proj tile (kind==1) contracts over
1416	//  K=Tp patch rows (not a multiple of 16); the SAME floor-balanced atom partition
1417	//  over KS=ceil(Tp/16) atoms works because the patch srcA/srcB already zero-guard
1418	//  k>=Tp (padded atoms contribute 0). kind==0 tiles contract over K=T or K=B
1419	//  (exact multiples of 16), exactly like the decoder.
1420	// ════════════════════════════════════════════════════════════════════════
1421	constexpr int kVitMaxTileN = SG_TUNED_TILE_N;                       // widest dW N-tile
1422	// Floats per (gt,kc) split-K slot: a work item is an M-atom GROUP of up to kVitDwIL
1423	// stacked m64 atoms → kVitDwIL·64 rows × N cols. (Was 64·N for the 1-atom item.)
1424	constexpr int kVitDwTileFloats = kVitDwIL * wgs::kWgmmaAtomM * kVitMaxTileN;
1425	
1426	// COMPILE-TIME max #dW output WORK ITEMS (the 10 dW have fixed Nout/Kin; ViT dims
1427	// are compile-time → constant). Mirrors vittc_dw_total_tiles at N=kVitMaxTileN. The
1428	// M factor is M-atom GROUPS of kVitDwIL (ceil(ceil(Nout/64)/kVitDwIL)), matching
1429	// vit_dw_groups — NOT single atoms.
1430	//   patch_proj(d×patch) + per-layer[qkv(3d×d),attn_out(d×d),ff0(dff×d),ff2(d×dff)]
1431	//   ×kLayers + head(V×d).
1432	constexpr int kVitDwMGroups(int Nout) {                 // ceil(ceil(Nout/64)/kVitDwIL)
1433	    return (((Nout + 63) / 64) + kVitDwIL - 1) / kVitDwIL;
1434	}
1435	constexpr int kVitDwTilesPerLayer =
1436	      kVitDwMGroups(3*vit::kD) * ((vit::kD   + kVitMaxTileN - 1)/kVitMaxTileN)   // qkv
1437	    + kVitDwMGroups(vit::kD)   * ((vit::kD   + kVitMaxTileN - 1)/kVitMaxTileN)   // attn_out
1438	    + kVitDwMGroups(vit::kDff) * ((vit::kD   + kVitMaxTileN - 1)/kVitMaxTileN)   // ff0
1439	    + kVitDwMGroups(vit::kD)   * ((vit::kDff + kVitMaxTileN - 1)/kVitMaxTileN);  // ff2
1440	constexpr int kVitDwPatchTiles =
1441	      kVitDwMGroups(vit::kD) * ((vit::kPatch + kVitMaxTileN - 1)/kVitMaxTileN);  // patch_proj
1442	constexpr int kVitDwHeadTiles =
1443	      kVitDwMGroups(vit::kVocab) * ((vit::kD + kVitMaxTileN - 1)/kVitMaxTileN);  // head
1444	constexpr int kVitDwMaxTiles =
1445	      kVitDwPatchTiles + vit::kLayers * kVitDwTilesPerLayer + kVitDwHeadTiles;
1446	
1447	// Split-K dW partial-scratch float count (host carves it from the workspace tail).
1448	// 0 when G==1 → no extra scratch (the single-CTA path is byte-identical). The total
1449	// (groups·kVitDwIL·64·N) == (atoms·64·N) for even atom counts; for ViT all 10 dW
1450	// have EVEN atom counts (2/6/2/8/2/2) so it is exactly unchanged vs the per-atom form.
1451	__host__ __device__ __forceinline__ int64_t vit_dw_part_floats(int G) {
1452	    return (G > 1) ? (int64_t)kVitDwMaxTiles * G * kVitDwTileFloats : 0;
1453	}
1454	
1455	// Decode global dW work-item index gt → (spec index s, m_group, n_tile). Single-
1456	// source (the SAME walk vittc_dw_run_tile + vittc_dw_total_tiles use): m_group
1457	// indexes M-atom GROUPS of kVitDwIL (group's first atom = m_group·kVitDwIL).
1458	template <int N>
1459	__device__ __forceinline__ void vittc_dw_decode(
1460	        const VitDwSpec spec[10], int gt, int& s, int& m_group, int& n_tile) {
1461	    int acc = 0;
1462	    for (s = 0; s < 10; ++s) {
1463	        const int ng = vit_dw_groups(spec[s].Nout);
1464	        const int nt = (spec[s].Kin + N - 1) / N;
1465	        if (gt < acc + ng * nt) { int loc = gt - acc; m_group = loc / nt; n_tile = loc % nt; return; }
1466	        acc += ng * nt;
1467	    }
1468	    s = 9; m_group = 0; n_tile = 0;   // unreachable (gt < n_dw); keep defined
1469	}
1470	
1471	// PARTIAL dW for global tile gt over K-chunk kc of G → dw_part. FLOOR-BALANCED
1472	// atom partition: chunk kc = [k0,k1) atoms with k0=floor(kc·KS/G),
1473	// k1=floor((kc+1)·KS/G) — near-equal, summing to KS EXACTLY for ANY KS≥G (no
1474	// `G | KS` requirement, so it works at the production batch where B/16 or
1475	// ceil(Tp/16) need not divide G). A CEIL split would leave a trailing EMPTY chunk
1476	// whose slot stays unwritten → the reduce sums garbage; floor never empties a
1477	// chunk for KS≥G, and a KS<G empty chunk is explicitly zeroed. Fresh ScaleD=0 per
1478	// chunk → true partial; writes the full 64×N tile (LOCAL rows) to the slot.
1479	template <int N>
1480	__device__ __forceinline__ void vittc_dw_run_tile_splitk(
1481	        const VitDwSpec spec[10], int gt, int kc, int G,
1482	        const __nv_bfloat16* __restrict__ dh0,
1483	        float* __restrict__ dw_part, __nv_bfloat16* sA, __nv_bfloat16* sB) {
1484	    int s, m_group, n_tile;
1485	    vittc_dw_decode<N>(spec, gt, s, m_group, n_tile);
1486	    const VitDwSpec& sp = spec[s];
1487	    const int n_atoms = vit_dw_atoms(sp.Nout);
1488	    const int a0 = m_group * kVitDwIL;                      // first atom of the group
1489	    const int g_atoms = (n_atoms - a0) < kVitDwIL ? (n_atoms - a0) : kVitDwIL;
1490	    const int mbase = a0 * 64;
1491	    const int n0 = n_tile * N;
1492	    const int Nout = sp.Nout, Kin = sp.Kin;
1493	    // KS = total k-atoms. kind==1 (patch_proj): K=Tp patch rows padded UP to /16.
1494	    // kind==0: K=T or K=B (already multiples of 16).
1495	    const int KS = (sp.kind == 1)
1496	        ? (((sp.K + wgs::kWgmmaAtomK - 1) / wgs::kWgmmaAtomK))   // ceil(Tp/16)
1497	        : (sp.K / wgs::kWgmmaAtomK);
1498	    const int k0 = (int)(((int64_t)kc       * KS) / G);          // floor-balanced
1499	    const int k1 = (int)(((int64_t)(kc + 1) * KS) / G);
1500	    const int kc_steps = k1 - k0;
1501	    // Slot holds the GROUP's kVitDwIL·64 local rows (lr) × N cols (kVitDwTileFloats).
1502	    float* slot = dw_part + ((int64_t)gt * G + kc) * kVitDwTileFloats;
1503	    // Empty-chunk guard (KS<G): a k_steps=0 GEMM would emit the uninitialized
1504	    // accumulator → zero the WHOLE group slot + return (the reduce sums all G slots;
1505	    // an empty chunk MUST be 0). Only g_atoms·64 rows are valid but zeroing the full
1506	    // kVitDwIL·64·N slot keeps it simple + safe (the reduce reads only valid rows).
1507	    if (kc_steps <= 0) {
1508	        for (int i = threadIdx.x; i < kVitDwTileFloats; i += blockDim.x) slot[i] = 0.0f;
1509	        __syncthreads();
1510	        return;
1511	    }
1512	    // out(mbase+row, col, v): m is GLOBAL (srcA needs it; engine adds mbase0=mbase);
1513	    // the slot holds the GROUP's kVitDwIL·64 LOCAL rows → index by (m - mbase). A
1514	    // ragged final group's tail rows stay zeroed/unwritten but the reduce reads only
1515	    // valid rows → never used. (A `lr<64` clamp would lose atom>=1's rows → the dW bug.)
1516	    auto out = [&] (int m, int n, float v) {
1517	        const int lr = m - mbase;
1518	        if (lr >= 0 && lr < kVitDwIL * 64 && n < N) slot[(int64_t)lr * N + n] = v; };
1519	    if (sp.kind == 1) {
1520	        // patch_proj: A[m=out,k=patchrow]=dh0[token row of patchrow, out] (transposed);
1521	        // B[n=in,k=patchrow]=X_patch[patchrow,in]. The k index here is the LOCAL chunk
1522	        // atom-step; the global patch row is (k0*16 + k). Pad rows (>=Tp) → 0.
1523	        const int Tp = sp.K;
1524	        const __nv_bfloat16* X = sp.X;
1525	        auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1526	            const int gk = k0 * wgs::kWgmmaAtomK + k;
1527	            if (m >= Nout || gk >= Tp) return __float2bfloat16(0.f);
1528	            const int si = gk / vit::kNPatch, p = gk % vit::kNPatch;
1529	            const int trow = si * vit::kSeq + (1 + p);
1530	            return dh0[(int64_t)trow * vit::kD + m]; };
1531	        auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1532	            const int gk = k0 * wgs::kWgmmaAtomK + k;
1533	            int nn = n0 + n; if (nn >= Kin || gk >= Tp) return __float2bfloat16(0.f);
1534	            return X[(int64_t)gk * Kin + nn]; };
1535	        tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kVitDwIL>(
1536	            mbase, g_atoms, /*n_real=*/N, kc_steps SG_VIT_DW_MREAL_ARG, srcA, srcB, out, sA, sB);
1537	        return;
1538	    }
1539	    // kind==0: A[m=out,k=t]=dY[t,out]; B[n=in,k=t]=X[t,in] (both transposed reads).
1540	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1541	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1542	        return m < Nout ? dY[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Nout + m] : __float2bfloat16(0.f); };
1543	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1544	        int nn = n0 + n; return nn < Kin ? X[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Kin + nn] : __float2bfloat16(0.f); };
1545	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kVitDwIL>(
1546	        mbase, g_atoms, /*n_real=*/N, kc_steps SG_VIT_DW_MREAL_ARG, srcA, srcB, out, sA, sB);
1547	}
1548	
1549	// Deterministic reduce: output work item gt (% nCTA) sums its G chunk-partials
1550	// ascending-kc → grad. SAME (gt → geometry) decode as the partial. Each work item
1551	// is an M-atom GROUP (up to kVitDwIL stacked m64 atoms, H3), so its slot holds the
1552	// group's kVitDwIL·64 group-local rows (row); mbase is the group's first global row.
1553	template <int N>
1554	__device__ __forceinline__ void vittc_dw_reduce_splitk(
1555	        const VitDwSpec spec[10], int n_dw, int G, const float* __restrict__ dw_part,
1556	        float* __restrict__ grad, int cta, int nCTA) {
1557	    for (int gt = cta; gt < n_dw; gt += nCTA) {
1558	        int s, m_group, n_tile;
1559	        vittc_dw_decode<N>(spec, gt, s, m_group, n_tile);
1560	        const VitDwSpec& sp = spec[s];
1561	        const int mbase = m_group * kVitDwIL * 64;          // group's first global row
1562	        const int n0 = n_tile * N;
1563	        const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1564	        // Valid group rows: up to kVitDwIL·64, clamped to the weight's row count.
1565	        const int grp_rows = kVitDwIL * 64;
1566	        const int Nrow = (sp.Nout - mbase) < grp_rows ? (sp.Nout - mbase) : grp_rows;
1567	        const int64_t base = (int64_t)gt * G * kVitDwTileFloats;
1568	        for (int idx = threadIdx.x; idx < Nrow * n_real; idx += blockDim.x) {
1569	            const int row = idx / n_real, col = idx % n_real;   // row = group-local lr
1570	            float accv = 0.0f;
1571	            for (int kc = 0; kc < G; ++kc)
1572	                accv += dw_part[base + (int64_t)kc * kVitDwTileFloats + (int64_t)row * N + col];
1573	            grad[sp.grad_off + (int64_t)(mbase + row) * sp.Kin + n0 + col] = accv;
1574	        }
1575	    }
1576	}
1577	
1578	// Biases db. For the 8 transformer linears + head: db = Σ_K dY (per output row).
1579	// For patch_proj.bias: db[o] = Σ_{patch rows} dh0[token row, o]. Single owner per
1580	// output element → no atomics.
1581	// PERF FIX (structural, parity-preserved — gated by the K-scaled grad tol, which is
1582	// designed for fp32 accumulation-order differences at large K):
1583	//   (1) The ORIGINAL ran the FULL Σ_K (K up to T=278528) for EVERY bias element on
1584	//       EVERY CTA (no cta/nCTA guard) — 132× redundant work, the dominant cost of P2
1585	//       grad-assembly (measured 59.5% of the step). Columns are now PARTITIONED across
1586	//       CTAs (each global bias column owned by one CTA), removing the 132× redundancy.
1587	//   (2) The K-reduction per column was SERIAL on ONE thread (≈278528 iters). It is now
1588	//       WARP-PARALLEL: a WARP (32 lanes) co-reduces one column — each lane sums a
1589	//       strided 1/32 slice of K (ascending within the lane), then a shuffle tree sums
1590	//       the 32 lane-partials. 32× parallelism per column. The lane reads dY[k*Nout+o]
1591	//       at fixed o with k = lane, lane+32, … (stride 32·Nout); writes by lane 0 only.
1592	__device__ __forceinline__ void vittc_dw_biases(
1593	        const VitDwSpec spec[10], const __nv_bfloat16* __restrict__ dh0,
1594	        float* __restrict__ grad, int cta, int nCTA) {
1595	    const int warp = threadIdx.x >> 5;            // 0..(blockDim/32 - 1)
1596	    const int lane = threadIdx.x & 31;
1597	    const int nwarps = blockDim.x >> 5;
1598	    int gcol_base = 0;
1599	    for (int s = 0; s < 10; ++s) {
1600	        const VitDwSpec& sp = spec[s];
1601	        const int Nout = sp.Nout;
1602	        const bool patch = (sp.kind == 1);
1603	        const int K = sp.K;
1604	        // Each warp owns columns o = (its rank among this CTA's warps), strided. A
1605	        // global column gcol is owned by CTA (gcol % nCTA); within the CTA the warps
1606	        // round-robin the owned columns.
1607	        for (int o = 0; o < Nout; ++o) {
1608	            const int gcol = gcol_base + o;
1609	            if ((gcol % nCTA) != cta) continue;       // not this CTA's column
1610	            // round-robin owned columns across warps: count owned-so-far for THIS s.
1611	            // Cheap: derive the warp owner from the o-th owned index. We instead let
1612	            // every warp test (owned_index % nwarps == warp); compute owned_index by
1613	            // a strided scan-free rule: owned columns appear every nCTA in gcol, so
1614	            // the k-th owned column of this CTA has o such that (gcol_base+o)%nCTA==cta.
1615	            // Assign by (o / 1) round-robin is fine since the inner reduce dominates:
1616	            // use (o-th column's position) — approximate with o itself for balance.
1617	            if (((o) % nwarps) != warp) continue;     // warp owns this column
1618	            float part = 0.0f;
1619	            if (patch) {
1620	                for (int k = lane; k < K; k += 32) {
1621	                    const int si = k / vit::kNPatch, p = k % vit::kNPatch;
1622	                    const int trow = si * vit::kSeq + (1 + p);
1623	                    part += __bfloat162float(dh0[(int64_t)trow * vit::kD + o]);
1624	                }
1625	            } else {
1626	                const __nv_bfloat16* dY = sp.dY;
1627	                for (int k = lane; k < K; k += 32)
1628	                    part += __bfloat162float(dY[(int64_t)k * Nout + o]);
1629	            }
1630	            // Warp-reduce the 32 lane-partials (shuffle tree).
1631	            #pragma unroll
1632	            for (int off = 16; off > 0; off >>= 1)
1633	                part += __shfl_down_sync(0xffffffffu, part, off);
1634	            if (lane == 0) grad[sp.bias_off + o] = part;
1635	        }
1636	        gcol_base += Nout;
1637	    }
1638	}
1639	
1640	// ════════════════════════════════════════════════════════════════════════
1641	//  P2 — CLS + POS owner-scan. dh0 [T,d] (bf16) holds grad wrt h0 (post-cat,
1642	//    pre-pos). cls_token grad = Σ_samp dh0[CLS row (pos 0)]; pos.weight[p] grad
1643	//    = Σ_t dh0[t] over t with (t%kSeq)==p (ALL 17 positions). Fixed t-order +
1644	//    single owner per element → deterministic, atomic-free. The owner of a
1645	//    feature j is round-robin (j % ... is implicit via thread stride; only ONE
1646	//    CTA — cta 0 — writes these tiny ([d] and [17×d]) tensors to avoid a
1647	//    cross-CTA race, since they are not tiled by gt). Mirrors the decoder
1648	//    embed owner-scan, ViT variant.
1649	// ════════════════════════════════════════════════════════════════════════
1650	__device__ __forceinline__ void vittc_clspos_owner_scan(
1651	        const VitActs& acts, int T, float* __restrict__ grad, int cta, int nCTA) {
1652	    const int cls_off = kVitOffsets[0];   // cls_token [1,1,d] → [d]
1653	    const int pos_off = kVitOffsets[3];   // pos.weight [kSeq, d]
1654	    const int nsamp = T / vit::kSeq;
1655	    // cls_token: owned by cta 0 (tiny [d]); each thread owns feature j.
1656	    if (cta == 0) {
1657	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
1658	            float accv = 0.0f;
1659	            for (int si = 0; si < nsamp; ++si)
1660	                accv += __bfloat162float(acts.dh0[(int64_t)(si * vit::kSeq) * vit::kD + j]);
1661	            grad[cls_off + j] = accv;
1662	        }
1663	    }
1664	    // pos rows: round-robin by position p across CTAs (p in [0,kSeq)).
1665	    // PERF FIX: the ORIGINAL looped ALL T tokens with `if (t%kSeq)==p`, doing 17×
1666	    // (kSeq) the necessary reads (keeping only 1/17). Token rows with t%kSeq==p are
1667	    // exactly t = p, p+kSeq, p+2·kSeq, … so stride DIRECTLY by kSeq (the same
1668	    // ascending-t order → bit-identical fp32 sum). 17× fewer reads.
1669	    for (int p = cta; p < vit::kSeq; p += nCTA) {
1670	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
1671	            float accv = 0.0f;
1672	            for (int t = p; t < T; t += vit::kSeq)
1673	                accv += __bfloat162float(acts.dh0[(int64_t)t * vit::kD + j]);
1674	            grad[pos_off + (int64_t)p * vit::kD + j] = accv;
1675	        }
1676	    }
1677	}
1678	
1679	// ════════════════════════════════════════════════════════════════════════
1680	//  P2 — LN-vector grad reduce. The 10 γ/β grads were accumulated tile-locally
1681	//    into each CTA's lnvec partials [kNumLnVec × d]; sum across CTAs in
1682	//    ASCENDING CTA index (deterministic) into the 10 vit_layout slots of grad.
1683	//    `lnvec_base` is the start of the [nCTA × kLnVecElems] partial region.
1684	// ════════════════════════════════════════════════════════════════════════
1685	__device__ __forceinline__ void vittc_lnvec_reduce(
1686	        const float* __restrict__ lnvec_base, float* __restrict__ grad,
1687	        int nCTA, int cta) {
1688	    for (int v = cta; v < kNumLnVec; v += nCTA) {
1689	        const int goff = kLnVecTensorIdx[v];
1690	        const int64_t gbase = kVitOffsets[goff];
1691	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
1692	            float accv = 0.0f;
1693	            for (int c = 0; c < nCTA; ++c)
1694	                accv += lnvec_base[(int64_t)c * kLnVecElems + (int64_t)v * vit::kD + j];
1695	            grad[gbase + j] = accv;
1696	        }
1697	    }
1698	}
