89	constexpr int kVocab   = SG_VIT_VOCAB;   // 97  (== p; head Linear(d, p))
90	constexpr int kD       = SG_VIT_D;       // 128
91	constexpr int kHeads   = SG_VIT_HEADS;   // 4
92	constexpr int kLayers  = SG_VIT_LAYERS;  // 2
93	constexpr int kPatch   = SG_VIT_PATCH;   // 49 (patch pixel count, 7×7)
94	constexpr int kNPatch  = SG_VIT_NPATCH;  // 16 image patches
95	constexpr int kSeq     = kNPatch + 1;    // 17 (CLS at 0, then 16 patches)
96	constexpr int kDff     = SG_VIT_DFF;     // 512
97	constexpr int kDhead   = kD / kHeads;    // 32
98	constexpr float kLnEps = 1e-5f;          // torch LayerNorm default
99	__device__ __forceinline__ float attn_scale() { return rsqrtf((float)kDhead); }
