343	// Self-attention (FULL — no causal mask) for one layer, CTA-cooperative. Reads
344	// q,k,v from sm->qkv columns [0,d),[d,2d),[2d,3d); writes softmax weights into
345	// sm->attn and the merged context into sm->ctx. Mirrors the oracle's attention.
346	__device__ __forceinline__ void vit_attention(VitSampleSmem* sm) {
347	    const float scale = vit::attn_scale();
348	    // One thread per (head, qpos) computes that row's softmax + ctx slice.
349	    // kSeq*kHeads = 68 rows; threads stride. Each thread loops d_head.
350	    for (int r = threadIdx.x; r < vit::kHeads * vit::kSeq; r += blockDim.x) {
351	        const int hh = r / vit::kSeq;     // head
352	        const int qi = r % vit::kSeq;     // query position
353	        const int qoff = hh * vit::kDhead;
354	        const float* qrow = &sm->qkv[qi][qoff];   // [dhead]
355	        float maxs = -CUDART_INF_F;
356	        float sc[vit::kSeq];
357	        #pragma unroll
358	        for (int kj = 0; kj < vit::kSeq; ++kj) {   // FULL: every key position
359	            const float* krow = &sm->qkv[kj][vit::kD + qoff];  // k block
360	            float dot = 0.0f;
361	            #pragma unroll
362	            for (int t = 0; t < vit::kDhead; ++t) dot += qrow[t] * krow[t];
363	            sc[kj] = dot * scale;
364	            maxs = fmaxf(maxs, sc[kj]);
365	        }
366	        float denom = 0.0f;
367	        #pragma unroll
368	        for (int kj = 0; kj < vit::kSeq; ++kj) {
369	            float e = __expf(sc[kj] - maxs);
370	            sc[kj] = e; denom += e;
371	        }
372	        float invd = 1.0f / denom;
373	        #pragma unroll
374	        for (int kj = 0; kj < vit::kSeq; ++kj)
375	            sm->attn[hh][qi][kj] = sc[kj] * invd;
376	        // ctx[qi, qoff+t] = sum_kj attn * v[kj, qoff+t]  (FULL: all kj)
377	        #pragma unroll
378	        for (int t = 0; t < vit::kDhead; ++t) {
379	            float acc = 0.0f;
380	            #pragma unroll
381	            for (int kj = 0; kj < vit::kSeq; ++kj)
382	                acc += sm->attn[hh][qi][kj] * sm->qkv[kj][2 * vit::kD + qoff + t];
383	            sm->ctx[qi][qoff + t] = acc;
384	        }
385	    }
386	    __syncthreads();
387	}
388	
389	// ────────────────────────────────────────────────────────────────────────────
390	//  FORWARD for one sample (CTA-cooperative). The sample's patches must already
391	//  be loaded into sm->patch. Writes the per-layer input cache + final-norm input
392	//  + CLS-position logits into `sm`, and returns the sample NLL (all threads see
393	//  the same value). Recompute-friendly: the layer-local scratch reflects the LAST
394	//  layer processed; backward recomputes per layer from layer_in.
395	// ────────────────────────────────────────────────────────────────────────────
396	// `inline` (vague linkage) REQUIRED — same reason as the decoder dec_* helpers:
397	// this header is now pulled by TWO co-resident _ops TUs (the scalar launcher
398	// mega_vit_real_adamw.cu AND the wired TC launcher mega_vit_real_adamw_tc_launcher.cu,
399	// -DSG_TUNED_GEMM_IMPL=1). These 5 non-template __device__ free fns would otherwise
400	// emit two strong definitions → "multiple definition" at host link (the template
401	// megakernels + __constant__ tables already merge/are-internal). inline lets the
402	// linker merge them; NOT __forceinline__ (large fns; forcing expansion is bloat).
403	__device__ inline float vit_forward_sample(const VitWeights& w, int target,
404	                                     VitSampleSmem* sm) {
405	    // Embedding: position 0 = cls + pos[0]; positions 1..16 = patch_proj(patch_i)
406	    //   + pos[1+i].  Build h0 into layer_in[0].
407	    // patch_proj -> rows 1..16 of layer_in[0] (write into a temporary region of
408	    // qkv, then add pos; but simplest: compute proj directly into layer_in[0]
409	    // rows 1.. via a linear over the 16 patch rows, with pos added after).
410	    // Step 1: cls row (position 0).
411	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x)
412	        sm->layer_in[0][0][j] = w.cls[j] + w.pos[j];   // pos[0] == w.pos + 0
413	    // Step 2: patch_proj over the 16 patch rows into ctx scratch [16,d].
414	    vit_linear(&sm->patch[0][0], vit::kPatch, w.patch_w, w.patch_b, vit::kD,
415	               &sm->ctx[0][0], vit::kNPatch);   // ctx[0..15] := proj
416	    // Step 3: add pos[1+i] -> layer_in[0] rows 1..16.
417	    for (int idx = threadIdx.x; idx < vit::kNPatch * vit::kD; idx += blockDim.x) {
418	        const int i = idx / vit::kD, j = idx % vit::kD;
419	        sm->layer_in[0][1 + i][j] = sm->ctx[i][j]
420	                                  + w.pos[(int64_t)(1 + i) * vit::kD + j];
421	    }
422	    __syncthreads();
423	
424	    for (int li = 0; li < vit::kLayers; ++li) {
425	        const VitWeights::Layer& L = w.layer[li];
426	        float* hin = &sm->layer_in[li][0][0];   // [kSeq, kD]
427	        // qkv = hin @ in_w^T + in_b -> [kSeq, 3d]
428	        vit_linear(hin, vit::kD, L.in_w, L.in_b, 3 * vit::kD, &sm->qkv[0][0],
429	                   vit::kSeq);
430	        // FULL attention -> sm->ctx, sm->attn.
431	        vit_attention(sm);
432	        // a = ctx @ out_w^T + out_b -> x1 (temporary 'a').
433	        vit_linear(&sm->ctx[0][0], vit::kD, L.out_w, L.out_b, vit::kD,
434	                   &sm->x1[0][0], vit::kSeq);   // x1 holds 'a' for now
435	        // r1 = hin + a -> ctx (reuse). n1(r1) -> x1.
436	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
437	            const int s = idx / vit::kD, j = idx % vit::kD;
438	            sm->ctx[s][j] = hin[s * vit::kD + j] + sm->x1[s][j];   // ctx := r1
439	        }
440	        __syncthreads();
441	        vit_layernorm_fwd(&sm->ctx[0][0], L.n1_w, L.n1_b, &sm->x1[0][0],
442	                          &sm->n1_xhat[0][0], &sm->n1_inv[0], sm->red);
443	        // FFN: ff0 = x1 @ ff0_w^T + ff0_b; g = gelu(ff0); ff2 = g @ ff2_w^T + b.
444	        vit_linear(&sm->x1[0][0], vit::kD, L.ff0_w, L.ff0_b, vit::kDff,
445	                   &sm->ff0[0][0], vit::kSeq);
446	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kDff; idx += blockDim.x)
447	            sm->gact[idx / vit::kDff][idx % vit::kDff] =
448	                vit_gelu(sm->ff0[idx / vit::kDff][idx % vit::kDff]);
449	        __syncthreads();
450	        // ff2 -> ctx scratch (reuse), then r2 = x1 + ff2, n2(r2) -> next layer_in.
451	        vit_linear(&sm->gact[0][0], vit::kDff, L.ff2_w, L.ff2_b, vit::kD,
452	                   &sm->ctx[0][0], vit::kSeq);   // ctx := ff2
453	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
454	            const int s = idx / vit::kD, j = idx % vit::kD;
455	            sm->ctx[s][j] = sm->x1[s][j] + sm->ctx[s][j];   // ctx := r2
456	        }
457	        __syncthreads();
458	        float* dst = (li + 1 < vit::kLayers) ? &sm->layer_in[li + 1][0][0]
459	                                             : &sm->final_in[0][0];
460	        vit_layernorm_fwd(&sm->ctx[0][0], L.n2_w, L.n2_b, dst,
461	                          &sm->n2_xhat[0][0], &sm->n2_inv[0], sm->red);
462	    }
463	
464	    // Final norm on the CLS position (0) only, then head → logits → NLL.
465	    const float* hcls = &sm->final_in[0][0];
466	    float sum = 0.0f;
467	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) sum += hcls[j];
468	    float mean = vit_block_sum(sum, sm->red) / (float)vit::kD;
469	    float vs = 0.0f;
470	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
471	        float c = hcls[j] - mean; vs += c * c;
472	    }
473	    float var = vit_block_sum(vs, sm->red) / (float)vit::kD;
474	    float inv = rsqrtf(var + vit::kLnEps);
475	    if (threadIdx.x == 0) sm->fn_inv[0] = inv;
476	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
477	        float xh = (hcls[j] - mean) * inv;
478	        sm->fn_xhat[0][j] = xh;                    // CLS xhat stored at row 0
479	        sm->x1[0][j] = xh * w.norm_w[j] + w.norm_b[j];   // x1[0] := hn
480	    }
481	    __syncthreads();
482	    // logits[o] = hn · out_w[o] + out_b[o]  (o over kVocab).
483	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) {
484	        const float* Wr = w.out_w + (int64_t)o * vit::kD;
485	        float acc = w.out_b[o];
486	        #pragma unroll 4
487	        for (int k = 0; k < vit::kD; ++k) acc += sm->x1[0][k] * Wr[k];
488	        sm->logits[o] = acc;
489	    }
490	    __syncthreads();
491	    // NLL (mean handled by /B in the loss reduce): logz - logits[target].
492	    float lmax = -CUDART_INF_F;
493	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x)
494	        lmax = fmaxf(lmax, sm->logits[o]);
495	    lmax = vit_block_max(lmax, sm->red);
496	    float es = 0.0f;
497	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x)
498	        es += __expf(sm->logits[o] - lmax);
499	    es = vit_block_sum(es, sm->red);
500	    float logz = lmax + __logf(es);
501	    return logz - sm->logits[target];   // sample NLL
502	}
503	
504	// ── Recompute one layer's forward intermediates into sm (qkv, x1, ff0, gact,
505	//    attn, and ctx := r2), reading from sm->layer_in[li]. Mirrors the fwd layer
506	//    body but leaves r2 in sm->ctx and x1 in sm->x1 for the backward chain. ─────
507	__device__ inline void vit_recompute_layer(const VitWeights& w, int li,
508	                                     VitSampleSmem* sm) {
509	    const VitWeights::Layer& L = w.layer[li];
510	    float* hin = &sm->layer_in[li][0][0];
511	    vit_linear(hin, vit::kD, L.in_w, L.in_b, 3 * vit::kD, &sm->qkv[0][0],
512	               vit::kSeq);
513	    vit_attention(sm);   // fills sm->attn + sm->ctx (== attention context)
514	    vit_linear(&sm->ctx[0][0], vit::kD, L.out_w, L.out_b, vit::kD, &sm->x1[0][0],
515	               vit::kSeq);   // x1 := a
516	    for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
517	        const int s = idx / vit::kD, j = idx % vit::kD;
518	        sm->ctx[s][j] = hin[s * vit::kD + j] + sm->x1[s][j];   // ctx := r1
519	    }
520	    __syncthreads();
521	    vit_layernorm_fwd(&sm->ctx[0][0], L.n1_w, L.n1_b, &sm->x1[0][0],
522	                      &sm->n1_xhat[0][0], &sm->n1_inv[0], sm->red);  // x1 := n1(r1)
523	    vit_linear(&sm->x1[0][0], vit::kD, L.ff0_w, L.ff0_b, vit::kDff, &sm->ff0[0][0],
524	               vit::kSeq);
525	    for (int idx = threadIdx.x; idx < vit::kSeq * vit::kDff; idx += blockDim.x) {
526	        const int s = idx / vit::kDff, j = idx % vit::kDff;
527	        sm->gact[s][j] = vit_gelu(sm->ff0[s][j]);
528	    }
529	    __syncthreads();
530	    // ff2 -> tmp (dh scratch, unused until bwd), r2 = x1 + ff2 -> ctx.
531	    vit_linear(&sm->gact[0][0], vit::kDff, L.ff2_w, L.ff2_b, vit::kD, &sm->dh[0][0],
532	               vit::kSeq);
533	    for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
534	        const int s = idx / vit::kD, j = idx % vit::kD;
535	        sm->ctx[s][j] = sm->x1[s][j] + sm->dh[s][j];   // ctx := r2
536	    }
537	    __syncthreads();
538	    // Fill n2 caches (we don't need n2's output for bwd, only xhat/inv).
539	    vit_layernorm_fwd(&sm->ctx[0][0], L.n2_w, L.n2_b, &sm->dh[0][0],
540	                      &sm->n2_xhat[0][0], &sm->n2_inv[0], sm->red);
541	    __syncthreads();
542	}
