544	// LayerNorm backward (same as decoder): given dy [kSeq,d] and cached (xhat,inv),
545	// returns dx [kSeq,d] into dx_out and ACCUMULATES dgamma/dbeta into gw/gb [d].
546	// Owner-thread rule for gw/gb: thread owns feature j (strided), sums over rows.
547	__device__ inline void vit_layernorm_bwd(
548	        const float* __restrict__ dy, const float* __restrict__ xhat,
549	        const float* __restrict__ inv, const float* __restrict__ gamma,
550	        float* __restrict__ dx_out, float* __restrict__ gw, float* __restrict__ gb,
551	        float* red, bool accum_affine) {
552	    if (accum_affine) {
553	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
554	            float dgw = 0.0f, dgb = 0.0f;
555	            #pragma unroll
556	            for (int s = 0; s < vit::kSeq; ++s) {
557	                float d = dy[s * vit::kD + j];
558	                dgb += d; dgw += d * xhat[s * vit::kD + j];
559	            }
560	            gw[j] += dgw; gb[j] += dgb;
561	        }
562	    }
563	    for (int s = 0; s < vit::kSeq; ++s) {
564	        const float* dyr = dy + s * vit::kD;
565	        const float* xhr = xhat + s * vit::kD;
566	        float sda = 0.0f, sdax = 0.0f;
567	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
568	            float dxhat = dyr[j] * gamma[j];
569	            sda += dxhat; sdax += dxhat * xhr[j];
570	        }
571	        sda = vit_block_sum(sda, red);
572	        sdax = vit_block_sum(sdax, red);
573	        float inv_s = inv[s];
574	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
575	            float dxhat = dyr[j] * gamma[j];
576	            dx_out[s * vit::kD + j] =
577	                inv_s * (dxhat - (sda + xhr[j] * sdax) / (float)vit::kD);
578	        }
579	        __syncthreads();
580	    }
581	}
582	
583	// dW += dY^T @ X for a linear Y = X @ W^T + b. dY [kSeq,out], X [kSeq,in],
584	// dW [out,in]. db[o] += sum_s dY[s,o]. dX [kSeq,in] = dY @ W into dx_out
585	// (set or accumulate per set_dx).
586	//
587	// ldY/ldX/ldDX are the ROW STRIDES (leading dimensions) of dY/X/dx_out. They are
588	// EXPLICIT (no defaults) — IDENTICAL contract to the decoder's dec_linear_bwd.
589	// The smem scratch buffers this is called on are 2D arrays whose DECLARED width
590	// (kDff=512 for ff0/gact) DIFFERS from the logical row width passed as
591	// out_dim/in_dim (dctx=kD=128, dqkv=3*kD=384). The original packed-stride form
592	// (dY[s*out_dim+o], X[s*in_dim+i], dx_out[s*in_dim+i]) silently read/wrote the
593	// WRONG rows at both attention-seam call sites: only row 0 partially landed,
594	// rows 1.. hit stale recomputed values — forward stayed exact while every grad
595	// upstream of attention was garbage (params decayed to zero under weight decay;
596	// train acc pinned at 1/97). The CPU structural mirror (vit_kernel_mirror.py)
597	// does NOT catch it (it indexes buffers semantically, not by flat offset), so the
598	// stride is now part of the call contract. W/dW stay at in_dim — those are the
599	// genuinely-packed param/grad tensors, not smem scratch.
600	__device__ inline void vit_linear_bwd(
601	        const float* __restrict__ dY, const float* __restrict__ X,
602	        const float* __restrict__ W, int in_dim, int out_dim,
603	        float* __restrict__ dW, float* __restrict__ db,
604	        float* __restrict__ dx_out, bool set_dx,
605	        int ldY, int ldX, int ldDX) {
606	    const int wtot = out_dim * in_dim;
607	    for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
608	        const int o = idx / in_dim, i = idx % in_dim;
609	        float acc = 0.0f;
610	        #pragma unroll
611	        for (int s = 0; s < vit::kSeq; ++s)
612	            acc += dY[s * ldY + o] * X[s * ldX + i];
613	        dW[(int64_t)o * in_dim + i] += acc;
614	    }
615	    if (db != nullptr) {
616	        for (int o = threadIdx.x; o < out_dim; o += blockDim.x) {
617	            float acc = 0.0f;
618	            #pragma unroll
619	            for (int s = 0; s < vit::kSeq; ++s) acc += dY[s * ldY + o];
620	            db[o] += acc;
621	        }
622	    }
623	    const int xtot = vit::kSeq * in_dim;
624	    for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
625	        const int s = idx / in_dim, i = idx % in_dim;
626	        float acc = 0.0f;
627	        for (int o = 0; o < out_dim; ++o)
628	            acc += dY[s * ldY + o] * W[(int64_t)o * in_dim + i];
629	        if (set_dx) dx_out[s * ldDX + i] = acc;
630	        else dx_out[s * ldDX + i] += acc;
631	    }
632	    __syncthreads();
633	}
634	
635	// ────────────────────────────────────────────────────────────────────────────
636	//  BACKWARD for one sample (CTA-cooperative). Assumes vit_forward_sample has run
637	//  for THIS sample (so layer_in/final_in/fn caches/logits + sm->patch are live).
638	//  Accumulates every weight grad into the CTA's partial buffer `g`.
639	//
640	//  Transcribed from tests/hw/vit_oracle.py::vit_backward (structurally mirrored
641	//  in tests/hw/vit_kernel_mirror.py).
642	// ────────────────────────────────────────────────────────────────────────────
643	__device__ inline void vit_backward_sample(const VitWeights& w, const VitGrad& g,
644	                                     int target, int B, VitSampleSmem* sm) {
645	    // ── CE backward: dlogits = (softmax - onehot)/B. ──
646	    float lmax = -CUDART_INF_F;
647	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x)
648	        lmax = fmaxf(lmax, sm->logits[o]);
649	    lmax = vit_block_max(lmax, sm->red);
650	    float es = 0.0f;
651	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x)
652	        es += __expf(sm->logits[o] - lmax);
653	    es = vit_block_sum(es, sm->red);
654	    float inv_es = 1.0f / es;
655	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) {
656	        float sm_o = __expf(sm->logits[o] - lmax) * inv_es;
657	        float dl = (sm_o - ((o == target) ? 1.0f : 0.0f)) / (float)B;
658	        sm->logits[o] = dl;   // overwrite logits[] with dlogits in place
659	    }
660	    __syncthreads();
661	    // ── head (out): logits = hn @ out_w^T + out_b. hn recomputed from the cached
662	    //    final-norm: hn[j] = fn_xhat[0][j]*norm_w[j] + norm_b[j]. ──
663	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) {
664	        float dl = sm->logits[o];
665	        g.out_b[o] += dl;
666	        float* gwrow = g.out_w + (int64_t)o * vit::kD;
667	        const float* xh = &sm->fn_xhat[0][0];
668	        #pragma unroll 4
669	        for (int j = 0; j < vit::kD; ++j) {
670	            float hn_j = xh[j] * w.norm_w[j] + w.norm_b[j];
671	            gwrow[j] += dl * hn_j;
672	        }
673	    }
674	    __syncthreads();
675	    // dhn[j] (feature-parallel) into dh row 0 scratch.
676	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
677	        float acc = 0.0f;
678	        for (int o = 0; o < vit::kVocab; ++o)
679	            acc += sm->logits[o] * w.out_w[(int64_t)o * vit::kD + j];
680	        sm->dh[0][j] = acc;   // dhn
681	    }
682	    __syncthreads();
683	    // ── final norm backward (single CLS row 0): dy=dhn, xhat=fn_xhat[0],
684	    //    inv=fn_inv[0]. Produces dh into dh[0]; zeros all other rows; accumulate
685	    //    dnorm_w/dnorm_b. Stage dy into ctx row 0. ──
686	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x)
687	        sm->ctx[0][j] = sm->dh[0][j];   // dy at CLS position
688	    __syncthreads();
689	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
690	        float d = sm->ctx[0][j];
691	        float xh = sm->fn_xhat[0][j];
692	        g.norm_b[j] += d; g.norm_w[j] += d * xh;
693	    }
694	    __syncthreads();
695	    {
696	        const float* dyr = &sm->ctx[0][0];
697	        const float* xhr = &sm->fn_xhat[0][0];
698	        float sda = 0.0f, sdax = 0.0f;
699	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
700	            float dxhat = dyr[j] * w.norm_w[j];
701	            sda += dxhat; sdax += dxhat * xhr[j];
702	        }
703	        sda = vit_block_sum(sda, sm->red);
704	        sdax = vit_block_sum(sdax, sm->red);
705	        float inv_s = sm->fn_inv[0];
706	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
707	            float dxhat = dyr[j] * w.norm_w[j];
708	            for (int s = 0; s < vit::kSeq; ++s) sm->dh[s][j] = 0.0f;
709	            sm->dh[0][j] = inv_s * (dxhat - (sda + xhr[j] * sdax) / (float)vit::kD);
710	        }
711	        __syncthreads();
712	    }
713	    // dh now = grad wrt the last layer's OUTPUT [kSeq,d] (only CLS pos 0 nonzero).
714	
715	    // ── per-layer backward (reverse). Each layer: recompute fwd intermediates,
716	    //    then apply the chain. The running adjoint `dh` is preserved across the
717	    //    recompute by SAVING it into final_in (free after fwd) around the
718	    //    recompute (which temporarily uses sm->dh as ff2 scratch). ─────────────
719	    for (int li = vit::kLayers - 1; li >= 0; --li) {
720	        const VitWeights::Layer& L = w.layer[li];
721	        const VitGrad::Layer& G = g.layer[li];
722	        // Save incoming adjoint dh into final_in — recompute clobbers sm->dh.
723	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
724	            const int s = idx / vit::kD, j = idx % vit::kD;
725	            sm->final_in[s][j] = sm->dh[s][j];
726	        }
727	        __syncthreads();
728	        vit_recompute_layer(w, li, sm);   // fills qkv,x1,ff0,gact,attn,ctx(=r2),caches
729	        // Restore dh (grad wrt h2 = n2 output).
730	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
731	            const int s = idx / vit::kD, j = idx % vit::kD;
732	            sm->dh[s][j] = sm->final_in[s][j];
733	        }
734	        __syncthreads();
735	        // n2 backward: dh -> dr2 (into ctx), accumulate n2 gamma/beta.
736	        vit_layernorm_bwd(&sm->dh[0][0], &sm->n2_xhat[0][0], &sm->n2_inv[0],
737	                          L.n2_w, &sm->ctx[0][0], G.n2_w, G.n2_b, sm->red, true);
738	        // r2 = x1 + ff2 -> dx1 (residual) := dr2 into fn_xhat; dr2 stays in ctx.
739	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
740	            const int s = idx / vit::kD, j = idx % vit::kD;
741	            sm->fn_xhat[s][j] = sm->ctx[s][j];   // dx1 := dr2 (residual part)
742	        }
743	        __syncthreads();
744	        // ff.2 backward. dW_ff2 += dr2^T @ g; db_ff2 += Σ dr2; then dff0 written
745	        // OVER gact (its forward value consumed by the dW GEMM first).
746	        {
747	            const float* dY = &sm->ctx[0][0];   // dr2 [kSeq,d]
748	            const float* X = &sm->gact[0][0];   // g [kSeq,4d]
749	            const int wtot = vit::kD * vit::kDff;
750	            for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
751	                const int o = idx / vit::kDff, i = idx % vit::kDff;
752	                float acc = 0.0f;
753	                #pragma unroll
754	                for (int s = 0; s < vit::kSeq; ++s)
755	                    acc += dY[s * vit::kD + o] * X[s * vit::kDff + i];
756	                G.ff2_w[(int64_t)o * vit::kDff + i] += acc;
757	            }
758	            for (int o = threadIdx.x; o < vit::kD; o += blockDim.x) {
759	                float acc = 0.0f;
760	                #pragma unroll
761	                for (int s = 0; s < vit::kSeq; ++s) acc += dY[s * vit::kD + o];
762	                G.ff2_b[o] += acc;
763	            }
764	            __syncthreads();
765	            const int xtot = vit::kSeq * vit::kDff;
766	            for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
767	                const int s = idx / vit::kDff, i = idx % vit::kDff;
768	                float dg = 0.0f;
769	                for (int o = 0; o < vit::kD; ++o)
770	                    dg += dY[s * vit::kD + o] * L.ff2_w[(int64_t)o * vit::kDff + i];
771	                sm->gact[s][i] = dg * vit_gelu_grad(sm->ff0[s][i]);  // gact := dff0
772	            }
773	            __syncthreads();
774	        }
775	        // ff.0 backward: dY=dff0(=gact), X=x1 -> dW ff0, db ff0, dx1 += dff0 @ ff0_w.
776	        {
777	            const float* dY = &sm->gact[0][0];   // dff0 [kSeq,4d]
778	            const float* X = &sm->x1[0][0];      // x1 [kSeq,d]
779	            const int wtot = vit::kDff * vit::kD;
780	            for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
781	                const int o = idx / vit::kD, i = idx % vit::kD;
782	                float acc = 0.0f;
783	                #pragma unroll
