1206	// Launcher (static-smem; the decoder TC contract). ncta_cap>0 caps the launched
1207	// CTAs (the per-CTA scratch is nCTA×slab; a memory-tight TEST caps it). Grid
1208	// barrier rendezvous is over the LAUNCHED count → hang-safe; determinism is per
1209	// fixed nCTA (dW-tile / partial / embed owner maps read ctx.n_ctas). B%16 req.
1210	// Host helper: the EXACT CTA count launch_fused_mamba_megakernel_tc<Opt> will use
1211	// (occ·n_sms with occupancy-fill, or the cap). The caller MUST size the workspace
1212	// with this — the per-CTA scratch/partials are nCTA·slab, so sizing for n_sms while
1213	// the launcher runs occ·n_sms would overflow. Returns 0 on a CUDA-attr failure (the
1214	// caller should treat that as "fall back to a conservative larger size").
1215	template <OptId Opt>
1216	int mb_tc_launched_nctas(int dev, int ncta_cap) {
1217	    int n_sms = 0;
1218	    if (cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev) != cudaSuccess) return 0;
1219	    // MAMBA-3: the per-sample MambaSampleSmem (~227 KB) is DYNAMIC smem → one
1220	    // block/SM (occ=1) by design. Query occ with the REAL dynamic-smem request
1221	    // (and opt in first, else the query assumes the 48 KB static default).
1222	    const int dyn_smem = (int)kMambaSmemBytes;
1223	    cudaFuncSetAttribute((const void*)&fused_mamba_megakernel_tc<Opt>,
1224	                         cudaFuncAttributeMaxDynamicSharedMemorySize, dyn_smem);
1225	    int occ = 0;
1226	    if (cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1227	            &occ, (const void*)&fused_mamba_megakernel_tc<Opt>, SG_MB_TC_MEGA_BLOCK, dyn_smem) != cudaSuccess)
1228	        return 0;
1229	    if (occ < 1) return 0;
1230	    unsigned launch_ctas = (unsigned)n_sms;   // one CTA/SM (smem-bound)
1231	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
1232	    return (int)launch_ctas;
1233	}
1234	
1235	template <OptId Opt>
1236	cudaError_t launch_fused_mamba_megakernel_tc(
1237	        PersistentContext ctx, float* params, MambaTokenCtx tok,
1238	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
1239	        int ncta_cap = 0) {
1240	    int dev = 0;
1241	    cudaError_t err = cudaGetDevice(&dev);
1242	    if (err != cudaSuccess) return err;
1243	    int n_sms = 0;
1244	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
1245	    if (err != cudaSuccess) return err;
1246	
1247	    // MAMBA-3: DYNAMIC smem opt-in (the per-sample MambaSampleSmem ~227 KB). Three
1248	    // mandatory steps (cudaFuncSetAttribute + dyn_smem in the occ query + dyn_smem
1249	    // at <<<>>>); one block/SM by design (occ=1, smem-bound).
1250	    const int dyn_smem = (int)kMambaSmemBytes;
1251	    err = cudaFuncSetAttribute((const void*)&fused_mamba_megakernel_tc<Opt>,
1252	                               cudaFuncAttributeMaxDynamicSharedMemorySize, dyn_smem);
1253	    if (err != cudaSuccess) return err;
1254	    int occ = 0;
1255	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1256	        &occ, (const void*)&fused_mamba_megakernel_tc<Opt>, SG_MB_TC_MEGA_BLOCK,
1257	        /*dynamicSMemBytes=*/dyn_smem);
1258	    if (err != cudaSuccess) return err;
1259	    if (occ < 1) return cudaErrorLaunchOutOfResources;
1260	
1261	    unsigned launch_ctas = (unsigned)n_sms;   // one CTA/SM (smem-bound); deterministic per fixed nCTA
1262	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
1263	    ctx.n_ctas = launch_ctas;
1264	    // B%16 kept (the gate truncates B to a multiple of 16; the scalar per-sample
1265	    // path needs no tile alignment but the contract upstream assumes B%16).
1266	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
1267	
1268	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
1269	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
1270	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
1271	
1272	    dim3 grid(launch_ctas), block(SG_MB_TC_MEGA_BLOCK);
1273	    fused_mamba_megakernel_tc<Opt><<<grid, block, dyn_smem, stream>>>(
1274	        ctx, params, tok, grad, lr, step, st);
1275	    return cudaGetLastError();
1276	}
